<template><Layout><div class="breadcrumb"><Link :href="route('verification-requests.index')">Verifications</Link><span>›</span>Request #{{ verificationRequest.id }}</div><div class="page-header review-header"><div><div class="eyebrow">IDENTITY REVIEW</div><h1>Review submission</h1><p>Submitted {{ fullDate(verificationRequest.created_at) }}</p></div><span class="verification request-status detail-status" :class="verificationRequest.status">{{ label(verificationRequest.status) }}</span></div><section class="review-grid"><div class="review-main"><article class="detail-card"><header><h2>Identity documents</h2><p>Compare both sides carefully before making a decision.</p></header><div class="review-documents"><a :href="verificationRequest.front_image" target="_blank"><div><img :src="verificationRequest.front_image"/><span>Open full size ↗</span></div><strong>NRC · Front side</strong></a><a :href="verificationRequest.back_image" target="_blank"><div><img :src="verificationRequest.back_image"/><span>Open full size ↗</span></div><strong>NRC · Back side</strong></a></div></article><article class="detail-card review-checklist"><header><h2>Review checklist</h2></header><label v-for="item in checklist" :key="item"><input v-model="checked" :value="item" type="checkbox"/><span>✓</span>{{ item }}</label></article></div><aside class="review-side"><article class="detail-card"><header><h2>Applicant</h2></header><div class="person-heading"><span>{{ initial(verificationRequest.user?.name) }}</span><div><strong>{{ verificationRequest.user?.name }}</strong><small>User #{{ verificationRequest.user?.id }}</small></div></div><div class="person-lines"><p><span>Phone</span><b>{{ verificationRequest.user?.phone||'—' }}</b></p><p><span>Email</span><b>{{ verificationRequest.user?.email||'—' }}</b></p><p><span>Address</span><b>{{ verificationRequest.user?.address||'—' }}</b></p><p><span>Member since</span><b>{{ dateOnly(verificationRequest.user?.member_since) }}</b></p></div><Link :href="route('users.show',verificationRequest.user.id)" class="panel-link">View full profile <span>→</span></Link></article><article v-if="verificationRequest.status==='pending'" class="detail-card decision-card"><header><h2>Review decision</h2><p>Approval immediately verifies this user.</p></header><textarea v-model="note" placeholder="Optional approval note, required for rejection…"></textarea><button class="approve-button" :disabled="processing||checked.length<checklist.length" @click="approve"><span v-if="processing" class="mini-spinner"></span>Approve verification</button><button class="reject-button" :disabled="processing||!note.trim()" @click="reject">Reject request</button><small v-if="checked.length<checklist.length">Complete all checklist items to approve.</small></article><article v-else class="detail-card review-outcome"><header><h2>Review outcome</h2></header><p><span>Decision</span><b>{{ label(verificationRequest.status) }}</b></p><p><span>Reviewer</span><b>{{ verificationRequest.reviewer?.name||'System' }}</b></p><p><span>Reviewed</span><b>{{ verificationRequest.reviewed_at?fullDate(verificationRequest.reviewed_at):'—' }}</b></p><div v-if="verificationRequest.review_note"><strong>Note</strong><p>{{ verificationRequest.review_note }}</p></div></article></aside></section></Layout></template>
<script setup>import{ref}from'vue';import{router}from'@inertiajs/vue3';import{route}from'ziggy-js';import Layout from'../Layouts/Layout.vue';const props=defineProps({verificationRequest:Object}),processing=ref(false),note=ref(''),checked=ref([]),checklist=['The document is clear and readable','Front and back appear to match','Identity details appear authentic'];const approve=()=>{processing.value=true;router.post(route('verification-requests.approve',props.verificationRequest.id),{review_note:note.value},{onFinish:()=>processing.value=false})};const reject=()=>{if(!window.confirm('Reject this verification request?'))return;processing.value=true;router.post(route('verification-requests.reject',props.verificationRequest.id),{review_note:note.value},{onFinish:()=>processing.value=false})};const label=s=>s.charAt(0).toUpperCase()+s.slice(1),initial=n=>(n||'?').charAt(0).toUpperCase(),fullDate=d=>new Intl.DateTimeFormat('en',{dateStyle:'long',timeStyle:'short'}).format(new Date(d)),dateOnly=d=>d?new Intl.DateTimeFormat('en',{dateStyle:'medium'}).format(new Date(d)):'—';</script>
